import React, { useEffect, useMemo, useRef, useState } from 'react';
import { Tag, Descriptions, Select, Input, Button } from 'antd';
import {
  CheckCircleOutlined,
  CloseCircleOutlined,
  RightOutlined,
  DownOutlined,
  ClockCircleOutlined,
  FileTextOutlined,
} from '@ant-design/icons';
import { formatDuration } from '../../utils/format';
import type { LogFlowGroup, LogEntry } from '../../logParser';
import { MAX_GROUP_ENTRY_PREVIEW, LOG_FLOW_INITIAL_COUNT, LOG_FLOW_LOAD_STEP, SEARCH_DEBOUNCE_MS } from '../../constants/analysisThresholds';
import useLoadMore from '../../hooks/useLoadMore';
import HighlightedText from './HighlightedText';
import LogRawContextModal from './LogRawContextModal';

interface LogFlowGroupsProps {
  groups: LogFlowGroup[];
  allEntries: LogEntry[];
  filterErrorOnly?: boolean;
}

type SortMode = 'default' | 'errorFirst' | 'slowest' | 'mostRequests';

type StatusFilter = 'all' | 'success' | 'error';

const LogFlowGroups: React.FC<LogFlowGroupsProps> = ({ groups, allEntries, filterErrorOnly }) => {
  const [expandedGroups, setExpandedGroups] = useState<Set<string>>(new Set());
  const [showDetailEntry, setShowDetailEntry] = useState<string | null>(null);
  const [sortMode, setSortMode] = useState<SortMode>('default');
  const [keyword, setKeyword] = useState('');
  const [debouncedKeyword, setDebouncedKeyword] = useState('');
  const [worker, setWorker] = useState<string>('all');
  const [level, setLevel] = useState<string>('all');
  const [status, setStatus] = useState<StatusFilter>('all');
  const [contextEntryId, setContextEntryId] = useState<string | null>(null);
  const debounceTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    if (debounceTimer.current) clearTimeout(debounceTimer.current);
    debounceTimer.current = setTimeout(() => setDebouncedKeyword(keyword.trim()), SEARCH_DEBOUNCE_MS);
    return () => {
      if (debounceTimer.current) clearTimeout(debounceTimer.current);
    };
  }, [keyword]);

  const filterOptions = useMemo(() => {
    const workerSet = new Set<string>();
    const levelSet = new Set<string>();
    groups.forEach(g => {
      g.entries.forEach(e => {
        if (e.worker) workerSet.add(e.worker);
        if (e.level) levelSet.add(e.level);
      });
    });
    return {
      workers: Array.from(workerSet).sort(),
      levels: Array.from(levelSet).sort(),
    };
  }, [groups]);

  const filteredGroups = useMemo(() => {
    const kw = debouncedKeyword.toLowerCase();
    const matchEntry = (e: LogEntry) => {
      if (worker !== 'all' && e.worker !== worker) return false;
      if (level !== 'all' && e.level !== level) return false;
      if (status === 'error' && e.status !== 'Error') return false;
      if (status === 'success' && e.status === 'Error') return false;
      if (!kw) return true;
      const hay = `${e.rawLine} ${e.url} ${e.friendlyName} ${e.statusText ?? ''} ${e.method} ${e.domain} ${e.path} ${e.worker} ${e.level}`.toLowerCase();
      return hay.includes(kw);
    };

    const mapped = groups.map(g => {
      const entries = g.entries.filter(matchEntry);
      const errorCount = entries.filter(e => e.status === 'Error').length;
      const successCount = entries.length - errorCount;
      const hasError = errorCount > 0;
      return {
        ...g,
        entries,
        errorCount,
        successCount,
        hasError,
        // summary 用于 header 折叠预览：优先显示匹配后的前几条
        summary: entries.slice(0, 3).map(e => e.friendlyName).join(' → ') || g.summary,
      };
    }).filter(g => g.entries.length > 0);

    const afterErrorOnly = filterErrorOnly ? mapped.filter(g => g.hasError) : mapped;
    return afterErrorOnly;
  }, [groups, debouncedKeyword, worker, level, status, filterErrorOnly]);

  const sortedGroups = useMemo(() => {
    const base = [...filteredGroups];
    switch (sortMode) {
      case 'errorFirst':
        return base.sort((a, b) => {
          if (a.hasError && !b.hasError) return -1;
          if (!a.hasError && b.hasError) return 1;
          return b.errorCount - a.errorCount;
        });
      case 'slowest': {
        const withTotal = base.map(g => ({
          ...g,
          totalDuration: g.entries.reduce((sum, e) => sum + e.duration, 0),
        }));
        return withTotal.sort((a, b) => b.totalDuration - a.totalDuration);
      }
      case 'mostRequests':
        return base.sort((a, b) => b.entries.length - a.entries.length);
      default:
        return base;
    }
  }, [filteredGroups, sortMode]);

  const { visibleItems: visibleGroups, hasMore, loadMore, remainingCount } = useLoadMore<LogFlowGroup>({
    items: sortedGroups,
    initialCount: LOG_FLOW_INITIAL_COUNT,
    step: LOG_FLOW_LOAD_STEP,
    resetDeps: [
      debouncedKeyword,
      worker,
      level,
      status,
      sortMode,
      filterErrorOnly,
    ],
  });

  const toggleGroup = (groupId: string) => {
    setExpandedGroups(prev => {
      const next = new Set(prev);
      if (next.has(groupId)) next.delete(groupId);
      else next.add(groupId);
      return next;
    });
  };



  const renderStep = (entry: LogEntry) => {
    const isError = entry.status === 'Error';

    return (
      <div key={entry.id} className="log-flow-step">
        <div className="log-flow-step-main">
          <span className={`log-flow-step-icon${isError ? ' log-flow-step-icon--error' : ''}`}>
            {isError ? <CloseCircleOutlined /> : <CheckCircleOutlined />}
          </span>
          <span className={`log-flow-step-name${isError ? ' log-flow-step-name--error' : ''}`}>
            <HighlightedText text={entry.friendlyName} keyword={debouncedKeyword} />
          </span>
          <code style={{ fontSize: 11, color: 'var(--text-muted)', fontFamily: 'var(--font-mono)' }}>
            {entry.id}
          </code>
          <Tag className="log-flow-step-method" color={isError ? 'error' : 'success'}>
            {entry.method}
          </Tag>
          <span className="log-flow-step-duration">
            <ClockCircleOutlined style={{ fontSize: 10 }} />
            {formatDuration(entry.duration)}
          </span>
          {isError && entry.statusText && (
            <Tag className="log-flow-step-status" color="error">
              <HighlightedText text={entry.statusText} keyword={debouncedKeyword} />
            </Tag>
          )}
          <button
            className="log-flow-step-detail-btn"
            onClick={(e) => {
              e.stopPropagation();
              setContextEntryId(entry.id);
            }}
          >
            <FileTextOutlined /> 上下文
          </button>
          <button
            className="log-flow-step-detail-btn"
            onClick={(e) => {
              e.stopPropagation();
              setShowDetailEntry(showDetailEntry === entry.id ? null : entry.id);
            }}
          >
            <FileTextOutlined /> 详情
          </button>
        </div>

        {showDetailEntry === entry.id && (
          <div className="log-flow-step-detail">
            <Descriptions column={1} className="log-flow-detail-desc">
              <Descriptions.Item label="URL">
                <HighlightedText text={entry.url} keyword={debouncedKeyword} />
              </Descriptions.Item>
              <Descriptions.Item label="时间">{entry.timestamp}</Descriptions.Item>
              <Descriptions.Item label="Worker">{entry.worker}</Descriptions.Item>
              <Descriptions.Item label="耗时">{entry.durationText}</Descriptions.Item>
              {entry.statusCode !== undefined && (
                <Descriptions.Item label="状态码">
                  {entry.statusCode} {entry.statusText || ''}
                </Descriptions.Item>
              )}
            </Descriptions>

            {Object.keys(entry.headers).length > 0 && (
              <div className="log-flow-detail-section">
                <div className="log-flow-detail-label">Headers</div>
                <pre className="log-flow-detail-pre">{JSON.stringify(entry.headers, null, 2)}</pre>
              </div>
            )}

            {entry.bodyRaw && (
              <div className="log-flow-detail-section">
                <div className="log-flow-detail-label">Body</div>
                <pre className="log-flow-detail-pre">
                  {entry.body ? JSON.stringify(entry.body, null, 2) : entry.bodyRaw}
                </pre>
              </div>
            )}
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="log-flow-groups">
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 10, marginBottom: 12, flexWrap: 'wrap' }}>
        <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
          <Input
            value={keyword}
            onChange={(e) => setKeyword(e.target.value)}
            placeholder="搜索（URL / 名称 / 原始行）"
            allowClear
            size="small"
            style={{ width: 260 }}
          />
          <Select
            value={worker}
            onChange={setWorker}
            size="small"
            style={{ width: 140 }}
            options={[
              { value: 'all', label: '全部 Worker' },
              ...filterOptions.workers.map(w => ({ value: w, label: w })),
            ]}
          />
          <Select
            value={level}
            onChange={setLevel}
            size="small"
            style={{ width: 120 }}
            options={[
              { value: 'all', label: '全部级别' },
              ...filterOptions.levels.map(l => ({ value: l, label: l })),
            ]}
          />
          <Select
            value={status}
            onChange={(v) => setStatus(v as StatusFilter)}
            size="small"
            style={{ width: 110 }}
            options={[
              { value: 'all', label: '全部状态' },
              { value: 'success', label: '仅成功' },
              { value: 'error', label: '仅失败' },
            ]}
          />
          <Button
            size="small"
            onClick={() => {
              setKeyword('');
              setWorker('all');
              setLevel('all');
              setStatus('all');
            }}
          >
            清空
          </Button>
        </div>

        <Select
          value={sortMode}
          onChange={setSortMode}
          style={{ width: 160 }}
          size="small"
          options={[
            { value: 'default', label: '默认顺序' },
            { value: 'errorFirst', label: '错误优先' },
            { value: 'slowest', label: '耗时最长' },
            { value: 'mostRequests', label: '请求最多' },
          ]}
        />
      </div>
      {visibleGroups.map((group) => {
        const isExpanded = expandedGroups.has(group.id);

        return (
          <div
            key={group.id}
            className={`log-flow-group${group.hasError ? ' log-flow-group--error' : ''}${isExpanded ? ' log-flow-group--expanded' : ''}`}
          >
            <div className="log-flow-group-header" onClick={() => toggleGroup(group.id)}>
              <div className="log-flow-group-header-left">
                <span className="log-flow-group-time">
                  {group.startTime}
                  {group.endTime !== group.startTime && ` ~ ${group.endTime}`}
                </span>
                <div className="log-flow-group-counts">
                  <span className="log-flow-group-count log-flow-group-count--success">
                    <CheckCircleOutlined /> {group.successCount}
                  </span>
                  {group.errorCount > 0 && (
                    <span className="log-flow-group-count log-flow-group-count--error">
                      <CloseCircleOutlined /> {group.errorCount}
                    </span>
                  )}
                </div>
                {(debouncedKeyword || worker !== 'all' || level !== 'all' || status !== 'all') && (
                  <Tag style={{ margin: 0 }} color="blue">
                    匹配 {group.entries.length} 条
                  </Tag>
                )}
                {group.hasError && (
                  <Tag color="error" className="log-flow-group-error-tag">失败</Tag>
                )}
              </div>
              <div className="log-flow-group-header-right">
                {!isExpanded && (
                  <span className="log-flow-group-summary">{group.summary}</span>
                )}
                <span className="log-flow-group-arrow">
                  {isExpanded ? <DownOutlined /> : <RightOutlined />}
                </span>
              </div>
            </div>

            {isExpanded && (
              <div className="log-flow-group-body">
                <div className="log-flow-group-steps">
                  {group.entries.slice(0, MAX_GROUP_ENTRY_PREVIEW).map((entry) => renderStep(entry))}
                </div>
                {group.entries.length > MAX_GROUP_ENTRY_PREVIEW && (
                  <div style={{ fontSize: 12, color: 'var(--text-muted)', padding: '8px 0 0 0', textAlign: 'center' }}>
                    该流程共 {group.entries.length} 条记录，仅展示前 {MAX_GROUP_ENTRY_PREVIEW} 条
                  </div>
                )}
              </div>
            )}
          </div>
        );
      })}

      {hasMore && (
        <div style={{ textAlign: 'center', padding: '16px 0' }}>
          <button
            onClick={loadMore}
            style={{
              padding: '8px 24px',
              borderRadius: 6,
              border: '1px solid var(--border-color)',
              background: 'var(--bg-elevated)',
              color: 'var(--text-primary)',
              cursor: 'pointer',
              fontSize: 13,
            }}
          >
            加载更多 ({remainingCount} 条剩余)
          </button>
        </div>
      )}

      <LogRawContextModal
        open={Boolean(contextEntryId)}
        onClose={() => setContextEntryId(null)}
        entries={allEntries}
        centerEntryId={contextEntryId}
        keyword={debouncedKeyword}
      />

      <style>{`
        .log-flow-groups {
          display: flex;
          flex-direction: column;
          gap: 10px;
        }
        .log-flow-group {
          background: var(--bg-surface);
          border: 1px solid var(--border-color);
          border-radius: 14px;
          overflow: hidden;
          transition: box-shadow 0.2s ease, border-color 0.2s ease;
        }
        .log-flow-group--error {
          border-color: rgba(255, 77, 79, 0.18);
        }
        .log-flow-group--expanded {
          box-shadow: 0 2px 12px rgba(0,0,0,0.04);
        }
        .log-flow-group-header {
          padding: 12px 18px;
          display: flex;
          align-items: center;
          justify-content: space-between;
          cursor: pointer;
          transition: background 0.15s ease;
          gap: 12px;
        }
        .log-flow-group--error > .log-flow-group-header {
          background: rgba(255, 77, 79, 0.03);
        }
        .log-flow-group-header:hover {
          background: var(--bg-elevated);
        }
        .log-flow-group-header-left {
          display: flex;
          align-items: center;
          gap: 12px;
          flex-shrink: 0;
          flex-wrap: wrap;
        }
        .log-flow-group-header-right {
          display: flex;
          align-items: center;
          gap: 10px;
          flex: 1;
          min-width: 0;
          justify-content: flex-end;
        }
        .log-flow-group-time {
          font-size: 13px;
          color: var(--text-secondary);
          font-family: 'SF Mono', 'Cascadia Code', monospace;
          font-size: 12px;
        }
        .log-flow-group-counts {
          display: flex;
          align-items: center;
          gap: 8px;
        }
        .log-flow-group-count {
          display: inline-flex;
          align-items: center;
          gap: 4px;
          font-size: 12px;
        }
        .log-flow-group-count--success { color: #52c41a; }
        .log-flow-group-count--error { color: #ff4d4f; }
        .log-flow-group-error-tag {
          font-size: 11px !important;
          margin: 0 !important;
          height: 20px !important;
          line-height: 20px !important;
          border-radius: 6px !important;
          padding: 0 8px !important;
        }
        .log-flow-group-summary {
          font-size: 12px;
          color: var(--text-muted);
          overflow: hidden;
          text-overflow: ellipsis;
          white-space: nowrap;
          flex: 1;
          min-width: 0;
        }
        .log-flow-group-arrow {
          color: var(--text-muted);
          font-size: 11px;
          flex-shrink: 0;
          transition: transform 0.2s ease;
        }
        .log-flow-group-body {
          padding: 16px 18px;
          border-top: 1px solid var(--border-color);
        }
        .log-flow-group-steps {
          display: flex;
          flex-direction: column;
          gap: 14px;
        }
        .log-flow-step {
          display: flex;
          flex-direction: column;
          gap: 0;
        }
        .log-flow-step-main {
          display: flex;
          align-items: center;
          gap: 8px;
          flex-wrap: wrap;
        }
        .log-flow-step-icon {
          font-size: 14px;
          color: #52c41a;
          flex-shrink: 0;
        }
        .log-flow-step-icon--error { color: #ff4d4f; }
        .log-flow-step-name {
          font-size: 13px;
          color: var(--text-primary);
        }
        .log-flow-step-name--error {
          color: #ff4d4f;
          font-weight: 500;
        }
        .log-flow-step-method {
          font-size: 11px !important;
          margin: 0 !important;
          padding: 0 6px !important;
          height: 18px !important;
          line-height: 18px !important;
          border-radius: 4px !important;
        }
        .log-flow-step-duration {
          font-size: 12px;
          color: var(--text-muted);
          display: inline-flex;
          align-items: center;
          gap: 3px;
        }
        .log-flow-step-status {
          font-size: 11px !important;
          margin: 0 !important;
          padding: 0 6px !important;
          height: 18px !important;
          line-height: 18px !important;
          border-radius: 4px !important;
        }
        .log-flow-step-detail-btn {
          display: inline-flex;
          align-items: center;
          gap: 4px;
          font-size: 12px;
          color: #0ea5e9;
          background: none;
          border: none;
          cursor: pointer;
          padding: 2px 6px;
          border-radius: 4px;
          transition: background 0.15s ease;
          font-family: inherit;
        }
        .log-flow-step-detail-btn:hover {
          background: rgba(14, 165, 233, 0.06);
        }
        .log-flow-step-detail {
          margin-top: 10px;
          padding: 14px;
          background: var(--bg-elevated);
          border-radius: 12px;
          border: 1px solid var(--border-color);
        }
        .log-flow-detail-desc {
          margin-bottom: 12px;
        }
        .log-flow-detail-section {
          margin-bottom: 12px;
        }
        .log-flow-detail-label {
          font-size: 12px;
          font-weight: 600;
          margin-bottom: 6px;
          color: var(--text-secondary);
        }
        .log-flow-detail-pre {
          margin: 0;
          padding: 10px;
          background: var(--bg-base);
          border-radius: 6px;
          font-size: 11px;
          line-height: 1.5;
          overflow: auto;
          max-height: 150px;
          color: var(--text-secondary);
        }
      `}</style>
    </div>
  );
};

export default LogFlowGroups;
